(()=>{
 'use strict';
 const $=id=>document.getElementById(id);
 const modal=$('cafeAmberChat'),input=$('amberChatInput'),thread=$('amberChatThread'),scroll=$('amberChatScroll'),intro=$('amberChatIntro');
 const suggested=['Tell me about yourself.','What project are you most proud of?','What stands out about you as a designer?','How do I view your projects?','How did you build this portfolio?'];
 // Each answer is a faithful portfolio-grounded starting draft, not a claim to a live model.
 const knowledge=[
  {keys:["about me","about yourself","about section","read your about","your about blurb","who is amber","what is amber like"],answer:"I'm a product designer based in Los Angeles who cares deeply about craft but is equally pragmatic about how things get built. I partner closely with product and engineering to turn complex problems into meaningful outcomes. My experience spans product and growth design, from generative research and product strategy to visual polish and QA. I've worked across teams of all sizes and industries, including enterprise B2B SaaS, HR tech, health insurance,

:["ukg", "performance", "feedback", "manager", "hr tech"],answer:"At UKG and Ultimate Software, I worked on HR-tech experiences including performance development, coaching, and mobile feedback. A recurring challenge was translating complex, desktop-oriented workflows into something practical for people who don't spend their workday at a desk. Phase 1 of the performance work shipped; Phase 2 hadn't shipped when I left."},
  {keys:["research", "interview", "discovery", "user testing", "survey", "reduce risk", "risk through research"],answer:"I'm very comfortable leading my own user research. I use it not just to learn what people want, but to inform product decisions and reduce risk before the team commits to building something. I tend to mix generative research, concept testing, and product metrics. On the homepage, for example, people were asking for notifications. We brought a notifications-center concept and a homepage concept into testing, and the homepage performed better. That gave us evidence to make the call rather than just going with whoever had the strongest opinion."},
  {

an acquisition. Some features I worked on were adopted by hundreds of organizations, and one of the first products I shipped won an HR-tech product award. These are examples from an older interview answer, so I'd want to check the specifics before using them as current résumé claims."},
 ];
 function tokens(s){return (s.toLowerCase().replace(/[^a-z0-9 ]/g,' ').match(/[a-z0-9]+/g)||[]).filter(x=>x.length>2)}
 function score(q,rec){let hay=rec.keys.join(' ');let v=0;for(let key of rec.keys){if(q.includes(key))v+=35+key.length/3;else {let ts=tokens(key),overlap=ts.filter(w=>tokens(q).includes(w)).length;v+=overlap>=2?(overlap/ts.length)*8:0;}}return v}
 function respond(q){const v=q.trim().toLowerCase();if(!v)return '';if(/^(hi|hello|hey|yo|sup)[!. ]*$/.test(v))return "Hey! 👋 What's on your mind? You can ask me about the projects, my design approach, or this café.";let sorted=knowledge.map(k=>({k,score:score(v,k)})).sort((a,b)=>b.score-a.score);if(sorted[0]?.score>=7)return sorted[0].k.answer;return "That's a good question. I don't have a reliable answer to that in my published portfoli

o material yet, and I'd rather not make something up. Try asking about my HealthSherpa or Calendly projects, how I work with engineers, or how I made this café. I'm also building out this version of the chat with more interview answers.";}
 function bubble(s,who){let row=document.createElement('div');row.className='amber-chat-msg '+who;if(who==='amber'){let pic=document.createElement('img');pic.src='assets/amber-chat-profile.png';pic.alt='';row.append(pic);}let wrap=document.createElement('div'),lab=document.createElement('div'),text=document.createElement('div');lab.className='amber-chat-name';lab.textContent=who==='amber'?'Amber':'You';text.className='amber-chat-bubble';text.textContent=s;wrap.append(lab,text);row.append(wrap);thread.append(row);scroll.scrollTop=scroll.scrollHeight;}
 function send(v){const q=v.trim();if(!q)return;intro.hidden=true;bubble(q,'user');bubble(respond(q),'amber');input.value='';input.focus();}
 $('amberChatSuggestions').replaceChildren(...suggested.map(q=>{let b=document.createElement('button');b.type='button';b.textContent=q;b.addEventListener('click',

()=>send(q));return b}));
 let oldFocus=null;
 window.cafeOpenAmberChat=()=>{oldFocus=document.activeElement;modal.hidden=false;input.focus();};
 function close(){modal.hidden=true;if(oldFocus?.isConnected)oldFocus.focus();}
 $('amberChatClose').addEventListener('click',close);
 modal.addEventListener('pointerdown',e=>{e.stopPropagation();if(e.target===modal)close()});
 $('amberChatForm').addEventListener('submit',e=>{e.preventDefault();send(input.value)});
 input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send(input.value)}});
 window.addEventListener('keydown',e=>{if(modal.hidden)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();close();return;}e.stopImmediatePropagation();},true);
})();
